local ActivityDojo  = import("Game.Dojo.ActivityDojo")
local ActivityUtils = import('Game.Activity.ActivityUtils')
local ECSComponent  = import("Frame.ECS.ECSComponent")

---@class ActivityComponent : ECSComponent
local ActivityComponent = Class("ActivityComponent",ECSComponent)


function ActivityComponent:__init()
    self.name = "ActivityComponent"

    ---@type ActivityDojo[]
    self._activityData = nil

    ---@type table<string, integer> @ 进入活动的时间戳缓存
    self.enterTimeMap_ = {}
    self._syncData = {}
end


function ActivityComponent:__delete()
    self._activityData = nil
    self.enterTimeMap_ = nil
    self._syncData     = nil
end


---初始化
---@param jsonData table
function ActivityComponent:Initial(jsonData)
    local activityData = {}
    for i, v in ipairs(checkTable(jsonData)) do
        local dojo = ActivityDojo.New()
        dojo:Fill(v)
        table.insert(activityData, dojo)
    end
    self:SetActivityData(activityData)
end


---设置活动数据
function ActivityComponent:SetActivityData(activityData)
    self._activityData = checkTable(activityData)
end


---获取活动数据
---@return ActivityDojo[]
function ActivityComponent:GetActivityData()
    return self._activityData
end


--- 获取活动进入时间戳
---@param activityUuid integer
---@return integer
function ActivityComponent:GetActivityEnterTime(activityUuid)
    if self.enterTimeMap_[tostring(activityUuid)] == nil then
        self.enterTimeMap_[tostring(activityUuid)] = ActivityUtils.GetActivityEnterTime(activityUuid)
    end
    return self.enterTimeMap_[tostring(activityUuid)]
end


--- 设置活动进入时间戳
---@param activityUuid integer
function ActivityComponent:SetActivityEnterTime(activityUuid)
    local newEnterTime = ActivityUtils.WriteActivityEnterTime(activityUuid)
    self.enterTimeMap_[tostring(activityUuid)] = newEnterTime
end

---获取整点活动数据
function ActivityComponent:OverseaSyncDataReq(cb)
    GameUtils.Request(Interfaces.OverseaSyncData, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            if cb then
                cb()
            end
            return
        end
        local jsonData = response.data
        local activities = jsonData.activity
        self:SetSyncData(jsonData)
        for k, v in pairs(activities) do
            local dojo = ActivityDojo.New()
            dojo:Fill(v)
            v = dojo
        end
        if cb then
            cb(activities,jsonData)
        end
    end)
end

---设置活动数据
---@param activityId integer
---@return ActivityDojo | nil
function ActivityComponent:GetDojoByActivityId(activityId)
    local dojo = nil
    for i, v in pairs(self:GetActivityData()) do
        if checkInt(v.id) == activityId then
            dojo = v 
            break
        end
    end
    return dojo
end

---@param dojo ActivityDojo
function ActivityComponent:AddActivityData(dojo)
    table.insert(self._activityData, dojo)
end

---设置同步数据
function ActivityComponent:SetSyncData(syncData)
    self._syncData = syncData
end

---获取同步数据
function ActivityComponent:GetSyncData()
    return checkTable(self._syncData)
end

---获取活动同步数据
function ActivityComponent:GetSyncActivityData()
   return checkTable(self:GetSyncData().activity) 
end

---获取限时连续礼包数据
function ActivityComponent:GetPayTimeChestData()
    return self:GetSyncActivityData().payTimeChestData
end

return ActivityComponent
